UPDATE erp_bookstore_content
original_title = #{title}, author = #{author}, genre = #{genre}, content_type = #{contentType}, schoolyear = #{schoolYear}, summary = #{summary}, keywords = #{keywords},
WHERE content_id = #{contentId}

UPDATE erp_bookstore_item
book_title = #{bookTitle}, publisher = #{publisher}, keywords = #{keywords},
WHERE bcode = #{bcode}

mapper.select:
SELECT i.bcode, i.content_id, i.book_title, i.publisher, i.keywords, bc.center_code, bc.state
FROM erp_bookstore_item i
LEFT JOIN erp_bookstore_item_center bc ON i.bcode = bc.bcode

    AND i.content_id = #{contentId}
    AND bc.state = #{state}
    AND i.publisher LIKE '%' + #{publisher} + '%'

